package net.civeira.phylax.feature.observe.observeddashboard.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.feature.observe.observeddashboard.domain.ObservedDashboardDefaultRangeOptions;

class DefaultRangeVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property default range of observed dashboard ")
  void test_default_range_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> DefaultRangeVO.tryFrom("_HOUR_"));
    Assertions.assertEquals(ObservedDashboardDefaultRangeOptions.HOUR,
        DefaultRangeVO.tryFrom("HOUR").getDefaultRange());
    Assertions.assertThrows(ConstraintException.class, () -> DefaultRangeVO.tryFrom(null));
    Assertions.assertEquals(ObservedDashboardDefaultRangeOptions.HOUR,
        DefaultRangeVO.from(ObservedDashboardDefaultRangeOptions.HOUR).getDefaultRange());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> DefaultRangeVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + ObservedDashboardDefaultRangeOptions.HOUR + "]",
        DefaultRangeVO.from(ObservedDashboardDefaultRangeOptions.HOUR).toString());
  }
}
